import heapq

def match(orders):
    trades = []
    seq_counter = 0

    # order storage: id -> order dict
    order_map = {}

    buy_heap = []   # entries: (-price, seq, order)
    sell_heap = []  # entries: (price, seq, order)

    def push_order(order):
        nonlocal buy_heap, sell_heap
        if order['side'] == 'buy':
            heapq.heappush(buy_heap, (-order['price'], order['seq'], order))
        else:
            heapq.heappush(sell_heap, (order['price'], order['seq'], order))

    def pop_valid_top(heap):
        # pop entries until we find a valid (active, qty>0) top, discard invalid ones
        while heap:
            entry = heap[0]
            order = entry[2]
            if not order['active'] or order['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return entry
        return None

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            order = order_map.get(oid)
            if order is not None:
                order['active'] = False
            continue

        oid = o[1]
        side = o[2]

        if typ == 'limit':
            price = o[3]
            qty = o[4]
        elif typ == 'ioc':
            price = o[3]
            qty = o[4]
        elif typ == 'market':
            price = None
            qty = o[3]
        else:
            continue

        order = {
            'id': oid,
            'side': side,
            'price': price,
            'qty': qty,
            'seq': seq_counter,
            'active': True
        }
        seq_counter += 1
        order_map[oid] = order

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = pop_valid_top(opp_heap)
            if top is None:
                break
            resting_order = top[2]
            resting_price = resting_order['price']

            if typ == 'market':
                matches = True
            elif side == 'buy':
                matches = (price >= resting_price)
            else:
                matches = (price <= resting_price)

            if not matches:
                break

            trade_qty = min(remaining, resting_order['qty'])
            if side == 'buy':
                buy_id = oid
                sell_id = resting_order['id']
            else:
                buy_id = resting_order['id']
                sell_id = oid

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            remaining -= trade_qty
            resting_order['qty'] -= trade_qty

            if resting_order['qty'] <= 0:
                resting_order['active'] = False
                heapq.heappop(opp_heap)
                # already popped as top via pop_valid_top logic (heap[0] check), ensure removal
            # if still has qty, leave it in heap (it's still at top position, will be checked again next loop)

        order['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            push_order(order)
        else:
            if remaining <= 0:
                order['active'] = False
            else:
                order['active'] = False

    return trades

